def parse_record(line):
    ident, raw_amount = line.split(":", 1)
    ident, raw_amount = ident.strip(), raw_amount.strip()
    if not ident:
        raise ValueError("empty record ID")
    amount = None if raw_amount == "not-a-number" else int(raw_amount)
    return {"id": ident, "amount": amount}
